function parseCSV(txt){const k=cfg();const rows=C.csvParse(txt.trim());if(!rows.length)return{rows:[],bad:[]};const head=rows.shift().map(h=>h.trim().toLowerCase());const out=[],bad=[];
  rows.forEach((r,i)=>{const o={};head.forEach((h,j)=>o[h]=(r[j]||'').trim());try{const x=k.csv.row(o);if(k.noAddress?(!x.lane||x.dep==null):(!x.name||isNaN(x.lat)||isNaN(x.lng)||!x.lat))bad.push(i+2);else out.push(x)}catch(e){bad.push(i+2)}});return{rows:out,bad}}
